class McpError(Exception):
    pass


# ЖУРНАЛ ВЫЗОВОВ — ЭТО ИЗМЕРЕНИЕ, А НЕ ОТЛАДОЧНЫЙ СЛЕД (наряд F-08).
#
# Строка матрицы заявляет десять действий («create», «read», «edit», …), и до сих пор связь
# «действие → проверка» восстанавливалась по ИМЕНИ строки приёмки: у семейства B3 имя несёт действие
# (`B3M.<режим>.<действие>`), у остальных — нет (`G01`, `FL04`, `HO.1`), и действие по имени не
# восстанавливалось вовсе. Переименование строк эту связь не доказывает: имя — это объявление, а не
# свидетельство. Здесь записывается то, ЧТО строка СДЕЛАЛА: каждый вызов инструмента в порядке
# исполнения. Принадлежность вызова строке выводится из ПОРЯДКА — строка пишется после своей работы,
# поэтому окно `calls_window` строки и есть её доказательство.
CALL_LOG = []


class Client:
    def __init__(self, host_exe, config):
        args = [host_exe]
        if config:
            args += ["--config", config]
        self.p = subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE, text=True, encoding="utf-8")
        self.n = 0
        self.log = []
        self.err_lines = []
        # Набор инструментов, ОБЪЯВЛЯЮЩИХ operation_id, читается из `tools/list` при первом
        # обращении. Вписанный руками список расходится с поставкой ровно тогда, когда поставку
        # меняют, — и прибор начинает посылать поле, которого схема не объявляет.
        self._op_id_tools = None
        # The host writes diagnostics to stderr continuously. Left unread, the pipe buffer fills
        # and the child blocks — which looks exactly like a hung server. Drain it in the background.
        self._stderr_thread = threading.Thread(target=self._pump_stderr, daemon=True)
        self._stderr_thread.start()

    def _pump_stderr(self):
        try:
            while True:
                line = self.p.stderr.readline() if self.p.stderr else ""
                if not line:
                    return
                self.err_lines.append(line.rstrip())
        except Exception:
            return

    def _write(self, msg):
        assert self.p.stdin is not None
        self.p.stdin.write(json.dumps(msg, ensure_ascii=False) + "\n")
        self.p.stdin.flush()

    def _read(self, want_id, timeout):
        deadline = time.time() + timeout
        while time.time() < deadline:
            line = self.p.stdout.readline() if self.p.stdout else ""
            if not line:
                if self.p.poll() is not None:
                    raise McpError(f"host exited rc={self.p.returncode}; stderr tail: {self.tail()}")
                time.sleep(0.02)
                continue
            line = line.strip()
            if not line:
                continue
            try:
                msg = json.loads(line)
            except json.JSONDecodeError:
                # A non-JSON line on stdout means the server leaked diagnostics into the protocol.
                self.log.append("STDOUT-POLLUTION: " + line[:200])
                continue
            if msg.get("id") == want_id:
                return msg
            # notifications/other ids: ignore but keep
            self.log.append("interleaved: " + line[:160])
        raise McpError(f"timeout waiting for id={want_id}")

    def call(self, method, params=None, timeout=180):
        self.n += 1
        me = self.n
        msg = {"jsonrpc": "2.0", "id": me, "method": method}
        if params is not None:
            msg["params"] = params
        self._write(msg)
        reply = self._read(me, timeout)
        if "error" in reply:
            raise McpError(f"{method}: {reply['error']}")
        return reply["result"]

    def notify(self, method, params=None):
        msg = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            msg["params"] = params
        self._write(msg)

    def tool(self, name, arguments, timeout=180):
        """tools/call → (is_error, structured envelope, raw result)."""
        result = self.call("tools/call", {"name": name, "arguments": arguments}, timeout=timeout)
        env = result.get("structuredContent")
        # Запись делается ДО возврата: окно строки должно содержать вызов даже тогда, когда строка
        # падает на разборе ответа. Иначе неудачная проверка выглядела бы как «вызова не было».
        CALL_LOG.append({
            "seq": len(CALL_LOG),
            "tool": name,
            "operation_id": (env or {}).get("operation_id"),
            "error": error_code(env),
            "status": (env or {}).get("status"),
            "verification_level": ((env or {}).get("verification") or {}).get("level"),
            "revision_before": (env or {}).get("revision_before"),
            "revision_after": (env or {}).get("revision_after"),
            "is_error": bool(result.get("isError", False)),
            # Режим и документ — из АРГУМЕНТОВ вызова, а не из конверта: конверт возвращает
            # `operation_id` клиента (uuid), а не идентификатор режима матрицы. Без этих двух полей
            # доказательство нельзя привязать к режиму иначе, как по привязке строк в матрице, — а
            # именно привязка и была пробелом (F-08).
            "mode": (arguments or {}).get("mode"),
            "document_id": (arguments or {}).get("document_id"),
            # ИМЕНА АРГУМЕНТОВ ВЫЗОВА — режим аргументов, а не их значения. Наряд
            # `DEPENDENCIES_FULL_CLOSURE_DEVELOPER_PROMPT.md` §3 переопределяет действие `read` для
            # строк общих зависимостей: адресное типизированное дочитывание объекта его устойчивым
            # адресом маршрутом, объявленным строкой матрицы (`read_route`), и сторож обязан
            # проверять маршрут ВМЕСТЕ С АРГУМЕНТАМИ АДРЕСА. Без этого поля окно вызова неотличимо
            # от обзора: `kompas_list_aux_geometry` с `name` — адресное чтение, тот же инструмент без
            # `name` — перечисление, а по одному имени инструмента эти два случая неразличимы.
            #
            # ЗНАЧЕНИЯ ЗДЕСЬ НЕ ХРАНЯТСЯ намеренно: они бывают длинными (списки точек, предикаты) и
            # раздули бы журнал; для проверки маршрута нужен ФАКТ ПЕРЕДАЧИ аргумента, а он виден по
            # имени. Отсутствие ключа у старых отчётов — это «не измерено», а не «аргументов не было»:
            # различие сохраняется и называется.
            "args_keys": sorted(str(k) for k in (arguments or {}).keys()),
        })
        return result.get("isError", False), env, result

    def declares_operation_id(self, name):
        """Объявляет ли инструмент `operation_id` В СВОЕЙ ЖЕ опубликованной схеме.

        Прибор обязан спрашивать это у поставки, а не помнить списком: у инструмента с
        `additionalProperties: false` поле, которого схема не объявляет, отвергается Host'ом ДО
        COM, и отказ продукта подменяется отказом прибора. Измерено 21.09.2026: список, вписанный
        руками, не содержал двух НОВЫХ инструментов чтения (`kompas_list_aux_geometry`,
        `kompas_list_sketch_entities`), и каждый их вызов отвечал `INVALID_ARGUMENT` с путём
        `$/operation_id` — восемь отказов из восьми у первого и пять из пяти у второго, тогда как
        без лишнего поля те же вызовы доходят до продукта.
        """
        if self._op_id_tools is None:
            tools = self.call("tools/list", {}).get("tools", [])
            self._op_id_tools = frozenset(
                t.get("name") for t in tools
                if "operation_id" in ((t.get("inputSchema") or {}).get("properties") or {}))
        return name in self._op_id_tools

    def tail(self):
        return "\n".join(self.err_lines[-25:])
    def close(self):
        try:
            if self.p.stdin:
                self.p.stdin.close()
            self.p.wait(timeout=10)
        except Exception:
            self.p.kill()


class Report:
    def __init__(self, title, path):
        self.title = title
        self.path = path
        self.rows = []
        # Граница окна вызовов. Строки, записанные ОДНИМ пакетом после общей работы, делят одно окно:
        # если двигать границу на каждой записи, вторая и последующие строки пакета получили бы
        # пустое окно и выглядели бы неподтверждёнными. Граница двигается только тогда, когда между
        # записями действительно были вызовы.
        self._mark = 0
        self._start = 0
        # Отпечаток того, что измерялось. Без него отчёт о приёмке поставки невозможно отличить от
        # отчёта о прогоне дерева исходников: одинаковые строки, одинаковая метрика, разные
        # бинари. Заполняется в main(), когда пути уже разрешены.
        self.context = {}
        # КОПИИ отчёта по другим путям. Основной путь — каталог ЭТОГО прогона; сюда попадают
        # прежнее общее имя («последний прогон») и явный путь приёмки поставки (`--report`).
        # Копия, а не перемещение: единственный экземпляр доказательств у прогона уже есть.
        self.mirror_paths = []

    def add(self, cid, desc, verdict, detail="", details=None):
        """`detail` — короткая сводка для строки; `details` — полные данные измерения.

        Разделение не косметическое: `detail` усечён (600 в файле, 300 на экране), и всё, что
        положено в него одного, исчезает именно тогда, когда нужно — при разборе отказа. Данные,
        которые обязаны быть предъявлены целиком (доказательство ссылок, отпечатки объектов),
        идут в `details` и не усекаются.
        """
        row = {"id": cid, "description": desc, "verdict": verdict, "detail": clip(detail, 600)}
        if details is not None:
            row["details"] = details
        # ОКНО ВЫЗОВОВ строки: [начало, конец) в журнале CALL_LOG. Это свидетельство того, что строка
        # ИСПОЛНИЛА, а не того, как она названа (см. CALL_LOG).
        end = len(CALL_LOG)
        if end > self._mark:
            self._start = self._mark
            self._mark = end
        row["calls_window"] = [self._start, self._mark]
        self.rows.append(row)
        print(f"  [{verdict:7}] {cid:6} {desc}"
              + (f"\n           {clip(detail, 300)}" if detail else ""))
        if details is not None:
            print("           details=" + json.dumps(details, ensure_ascii=False))

    def save(self):
        payload = {"title": self.title}
        if self.context:
            payload["context"] = self.context
        payload["rows"] = self.rows
        if CALL_LOG:
            # Журнал едет ВМЕСТЕ с отчётом: без него `calls_window` некуда приложить, и связь
            # «действие → проверка» снова пришлось бы выводить из имени строки.
            payload["calls"] = CALL_LOG
            payload["calls_note"] = (
                "Вызовы инструментов в порядке исполнения. `rows[].calls_window` = [начало, конец) в "
                "этом списке; строка подтверждает ДЕЙСТВИЕ, если её окно содержит вызовы, требуемые "
                "подписью действия, а подпись калибруется на строках `B3M.<режим>.<действие>`, где "
                "действие названо именем строки (scratch/_build_api_compliance.py, action_signatures).")
        with open(self.path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2)
        for mirror in self.mirror_paths:
            target = os.path.abspath(mirror)
            if target == os.path.abspath(self.path):
                continue
            os.makedirs(os.path.dirname(target), exist_ok=True)
            shutil.copyfile(self.path, target)
            print(f"  копия отчёта: {target}")
        counts = {}
        for r in self.rows:
            counts[r["verdict"]] = counts.get(r["verdict"], 0) + 1
        print(f"\nИтог: {counts}")
        return counts



def error_code(envelope):
    """Error code of an envelope, tolerating "error": null on success.

    dict.get("error", {}) does not help when the key is present and null — which is the shape of
    every successful response — so the follow-up .get() would crash on None.
    """
    error = (envelope or {}).get("error")
    return error.get("code") if isinstance(error, dict) else None


def unverified_of(envelope):
    """Неподтверждённые аспекты конверта — из ОБОИХ мест, где продукт их публикует.

    Место публикации зависит от инструмента, и это измерено, а не предположено (журнал
    `scratch/journals/b3-operations.jsonl`, 18.09.2026):

    * `result.unverified_aspects` — так публикуют семейства B3 (`kompas_boolean` 127 вызовов,
      `kompas_split` 54, `kompas_cut_by_plane` 41, `kompas_reposition` 60) и `kompas_finish_sketch`.
      У этих инструментов блока `verification` в полезной нагрузке НЕТ ВООБЩЕ.
    * `verification.unverified_aspects` — так публикуют `kompas_extrude`, `kompas_update_feature`,
      `kompas_set_feature_suppressed`, `kompas_delete_feature`.

    Зачем читать оба. Клиент, читающий только документированное поле `verification.unverified_aspects`
    (Envelope.cs: «must list everything the level does not cover»), у инструментов B3 видит НЕ ответ
    адаптера, а подстановку хоста — `["geometry_or_file_effect_verified_in_worker_payload"]`, потому что
    хост подставляет консервативный уровень, когда полезная нагрузка блока не несёт. Настоящее
    расхождение при этом лежит рядом, в `result.unverified_aspects`. Прибор обязан видеть оба, иначе
    он читает не то поле и проходит с ЛЮБЫМ объявленным числом.

    Ровно так и было: до этой правки `expected_volume_mismatch` искали на ВЕРХНЕМ уровне конверта,
    где этого ключа нет ни у одного инструмента. Контрольная строка B3.40 (объявлено 36000 при сумме
    37000) на этом и упала — единственная во всей группе B3.
    """
    found = []
    result = (envelope or {}).get("result")
    if isinstance(result, dict):
        found.extend(result.get("unverified_aspects") or [])
    verification = (envelope or {}).get("verification")
    if isinstance(verification, dict):
        found.extend(verification.get("unverified_aspects") or [])
    return found


def clip(text, limit):
    """Обрезать длинный текст, ПОМЕТИВ место обрезки.

    Сообщения продукта длиннее, чем разумно класть в строку отчёта, поэтому их обрезают. Но
    обрезка без пометки неотличима от дефекта продукта: в отчёте поставки 18.09.2026 сообщение
    RO.2 читалось как «объём вырос на 502» — обрыв пришёлся ровно на число 50265.4824574366, и
    читатель видел бессмысленное «502» там, где продукт написал полное число. Отчёт обязан
    различать «продукт сказал это» и «здесь обрезал прибор».
    """
    if text is None:
        return ""
    text = str(text)
    if len(text) <= limit:
        return text
    return f"{text[:limit]}… [обрезано прибором: {len(text)} символов]"


def clear_path(path):
    """Освободить путь для файла этого прогона, НЕ удаляя прежний.

    Строки приёмки проверяют «файл создан ИМЕННО этой операцией», поэтому на пути не должно быть
    прежнего файла. Раньше здесь стоял `os.remove`, и 18.09.2026 приёмка поставки на этом
    оборвалась: среда исполнения считает удаления за ход и после 50-го прерывает процесс — прогон
    умирал на середине группы без следа в отчёте, а `rc=1` выглядел как дефект продукта.
    Переименование решает ту же задачу и не разрушает прежнюю модель: она остаётся рядом и
    пригодна для сравнения «до/после».
    """
    if not os.path.exists(path):
        return
    index = 1
    while True:
        candidate = f"{path}.prev-{index}"
        if not os.path.exists(candidate):
            os.replace(path, candidate)
            return
        index += 1


def file_sha256(path):
    """SHA-256 файла или пустая строка, если его нет.

    Отпечаток, а не путь: два разных бинаря могут лежать по одному пути, и «я запускал
    поставку» без хеша — это утверждение о каталоге, а не о том, что исполнилось.
    """
    try:
        digest = hashlib.sha256()
        with open(path, "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                digest.update(chunk)
        return digest.hexdigest()
    except OSError:
        return ""


