    # ── SM-02.cut_extrusion.blind (F08.06) ────────────────────────────────────────────────────
    def mk_cut(depth, offset, direction, tag, end_condition="blind"):
        def build(doc, rev):
            rev, body, _ref, code = mk_plate(doc, rev, tag)
            if code:
                return None, rev, "пластина: " + str(code)
            sk, rev, err = sketch(doc, rev, [HOLE], tag + "-cut", offset=offset)
            if err:
                return None, rev, err
            kw = {"operation": "cut", "direction": direction,
                  "end_condition": end_condition, "target_body_ref": body}
            if end_condition != "through":
                kw["depth_mm"] = depth
            rev, ref, code, _e = extrude(doc, rev, sk, **kw)
            return ref, rev, code
        return build

    def ed_depth(new_depth):
        def run(doc, rev, fref):
            env, code = call("kompas_update_feature", {
                "feature_ref": fref, "expected_revision": ctx(doc), "depth_mm": new_depth})
            return rev, code
        return run

    def ed_cut_end(end_condition, depth):
        """Правка УСЛОВИЯ ОКОНЧАНИЯ выреза — единственный существенный параметр сквозного режима.

        Обе половины передаются вместе и осознанно: `end_condition=through` с `depth_mm` запрещены
        контрактом ВМЕСТЕ (Api5Session.Features.cs:326), поэтому переход сквозное → глухое обязан
        назвать и условие, и глубину, иначе глубина останется неопределённой.
        """
        def run(doc, rev, fref):
            env, code = call("kompas_update_feature", {
                "feature_ref": fref, "expected_revision": ctx(doc),
                "end_condition": end_condition, "depth_mm": depth})
            return rev, code
        return run

