    def ed_fillet_edge_set(doc, rev, fref):
        """Сокращение набора 4 → 3 маршрутом API7: `base_object_refs` — ссылки СОБСТВЕННЫХ входов
        признака (`base_object_input_refs`). Измерено строкой FL10: набор сокращается, и объём
        становится объёмом трёх углов — то есть правка набора РАЗЛИЧИМА числом."""
        res = read_feature(fref) or {}
        handles = ((res.get("fillet") or {}).get("base_object_input_refs")) or []
        if len(handles) != 4:
            return rev, f"входов признака {len(handles)}, ожидалось 4"
        env, code = call("kompas_update_feature", {
            "feature_ref": fref, "expected_revision": ctx(doc),
            "base_object_refs": list(handles[:3])})
        return rev, code

