    # ── SM-11: фаска ──────────────────────────────────────────────────────────────────────────
    def mk_chamfer(mode, tag, d1, d2=None, angle=None, direction=None):
        def build(doc, rev):
            rev, body, _ref, code = mk_plate(doc, rev, tag)
            if code:
                return None, rev, "пластина: " + str(code)
            erefs = corner_edges(doc, body)
            if len(erefs) != 4:
                return None, rev, f"угловых рёбер {len(erefs)}, ожидалось 4"
            args = {"edge_refs": erefs, "mode": mode, "distance1_mm": d1,
                    "expected_revision": rev}
            if d2 is not None:
                args["distance2_mm"] = d2
            if angle is not None:
                args["angle_deg"] = angle
            if direction is not None:
                args["direction"] = direction
            env, code = call("kompas_chamfer", args)
            rev = (env or {}).get("revision_after") or rev
            return (result(env).get("feature_ref") or {}).get("id"), rev, code
        return build

    def ed_chamfer(**patch):
        def run(doc, rev, fref):
            env, code = call("kompas_update_feature", dict(
                {"feature_ref": fref, "expected_revision": ctx(doc)}, **patch))
            return rev, code
        return run

    def chamfer_negatives(doc, rev, own_name):
        """Отказы фаски на УЖЕ ПОСТРОЕННОМ теле: рёбра берутся ИЗ МОДЕЛИ, а не выдумываются.

        Все четыре случая отвергаются КОНТРАКТОМ до COM (измерено шагом P6 зонда: катет 0,
        отрицательный катет, угол больше 90° и пустой список рёбер дают INVALID_ARGUMENT с текстом
        «Аргументы не прошли контракт»). Рёбра передаются настоящие, чтобы отказ нельзя было
        объяснить «ссылка не найдена» — иначе проверка отказывала бы по чужой причине.
        """
        body = body_at(doc, (-50.0, -40.0, 0.0), (50.0, 40.0, 10.0))
        erefs = corner_edges(doc, body) if body else []
        return neg_chamfer_cases(doc, rev, erefs)

